#!/usr/bin/env bash
# generate-pipelines.sh — regenerate pipelines.bats from pipelines.tsv.
#
# Same pattern as generate-tests.sh (which builds smoke.bats). We emit static
# @test functions so bats sees them at parse time — far less fragile than
# constructing them dynamically with eval.

set -euo pipefail

HERE="$(dirname "$(readlink -f "$0")")"
MANIFEST="${HERE}/pipelines.tsv"
OUT="${HERE}/pipelines.bats"

[[ -f "$MANIFEST" ]] || { echo "manifest not found: $MANIFEST" >&2; exit 1; }

{
cat <<'HEADER'
#!/usr/bin/env bats
# AUTOGENERATED from pipelines.tsv by generate-pipelines.sh — do not edit manually.
#
# Each test gets a per-test $TMP (auto-cleaned) and inherits $FIX pointing at
# the synthesized fixtures dir. Skips cleanly when fixtures or the package
# under test are missing — never produces a false failure for an absent dep.

bats_require_minimum_version 1.5.0

HERE="$(dirname "${BATS_TEST_FILENAME}")"
export FIX="${HERE}/fixtures"

setup_file() {
    export NEUROFEDORA_TESTS=1
    if [[ ! -f "$FIX/t1.nii.gz" ]]; then
        if [[ -x "$FIX/generate-fixtures.sh" ]]; then
            "$FIX/generate-fixtures.sh" >&2 || true
        fi
    fi
}

setup()    { export TMP="$(mktemp -d -t neurofedora-pipe.XXXXXX)"; }
teardown() { [[ -n "${TMP:-}" && -d "$TMP" ]] && rm -rf "$TMP"; }

_require_installed() {
    rpm -q --quiet "$1" 2>/dev/null || skip "$1 not installed"
}

_require_fixtures() {
    [[ -f "$FIX/t1.nii.gz" ]] \
        || skip "fixtures missing (run fixtures/generate-fixtures.sh)"
}

# Real-world fixture set — MRI (MNI152), robotics URDFs, MorpheusML
# examples, BED genomics samples — all fetched by fetch-real-fixtures.sh.
# Accepts an optional path argument so each test can guard on its own
# specific file (the fetcher's sections are independent; one may have
# succeeded while another failed offline).
_require_real_fixtures() {
    local file="${1:-$FIX/real/mni152_t1_2mm.nii.gz}"
    [[ -f "$file" ]] \
        || skip "real fixture missing: $file (run fixtures/fetch-real-fixtures.sh)"
}

HEADER

awk -F'\t' '
    BEGIN { row = 0 }
    /^[[:space:]]*$/ { next }
    /^[[:space:]]*#/ { next }
    NF < 2           { next }
    {
        row += 1
        pkg = $1
        cmd = $2
        expect = (NF >= 3 ? $3 : "")

        # Same conda-safety rewrite as generate-tests.sh: force `python3 ` to
        # the system interpreter so the tests always see the RPMs in
        # /usr/lib/python3.X/site-packages, never whatever a conda/venv has
        # in PATH. Needs gawk (Fedora default) — uses gensub for backref support.
        cmd = gensub(/(^|[ \t])python3 /, "\\1/usr/bin/python3 ", "g", cmd)

        # Strip surrounding whitespace and trailing CRs that creep in from
        # editors.
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", pkg)
        gsub(/\r$/, "", cmd)
        gsub(/\r$/, "", expect)

        # Title: pkg + first 70 chars of the command (for `bats -p` legibility).
        title = cmd
        if (length(title) > 70) title = substr(title, 1, 70) "…"

        # Escape for double-quoted bash strings.
        e_cmd    = cmd;    gsub(/\\/, "\\\\", e_cmd);    gsub(/"/, "\\\"", e_cmd);    gsub(/\$/, "\\$", e_cmd)
        e_expect = expect; gsub(/\\/, "\\\\", e_expect); gsub(/"/, "\\\"", e_expect)
        e_title  = title;  gsub(/\\/, "\\\\", e_title);  gsub(/"/, "\\\"", e_title)

        # Auto-detect whether this row needs the real-data fixture set
        # (fetched by fetch-real-fixtures.sh). A row qualifies if its
        # command references $FIX/real/, and we extract the FIRST such
        # path so the skip can name the specific missing file rather than
        # generically "real fixtures missing".
        needs_real = (cmd ~ /\$FIX\/real\//)
        real_file = ""
        if (needs_real) {
            tmp = cmd
            # match up to and including .nii.gz / .urdf / .xml / .bed /
            # .sizes — same set the fetcher produces.
            if (match(tmp, /\$FIX\/real\/[A-Za-z0-9._\/-]+\.(nii\.gz|urdf|xml|bed|sizes|bb)/))
                real_file = substr(tmp, RSTART, RLENGTH)
        }

        printf "\n"
        # Prefix the title with a row number — guarantees uniqueness even
        # when two manifest lines share an identical command prefix (bats
        # hashes long titles into function names and would collide otherwise).
        printf "@test \"[%03d] %s: %s\" {\n", row, pkg, e_title
        if (needs_real) {
            if (real_file != "")
                printf "    _require_real_fixtures \"%s\"\n", real_file
            else
                printf "    _require_real_fixtures\n"
        } else {
            printf "    _require_fixtures\n"
        }
        printf "    _require_installed \"%s\"\n", pkg
        # We deliberately do NOT escape $ inside cmd above for $FIX/$TMP/$PATH —
        # the command is expected to reference these. Use heredoc to avoid all
        # escaping pain: the test runs the manifest line verbatim through bash.
        printf "    run --separate-stderr bash <<'PIPECMD'\n"
        printf "%s\n", cmd
        printf "PIPECMD\n"
        printf "    if [ \"$status\" -ne 0 ]; then\n"
        printf "        echo \"command failed (exit=$status)\"\n"
        printf "        echo \"stdout: $output\"\n"
        printf "        echo \"stderr: $stderr\"\n"
        printf "        false\n"
        printf "    fi\n"
        if (expect != "") {
            printf "    if ! grep -qE \"%s\" <<<\"$output $stderr\"; then\n", e_expect
            printf "        echo \"expected /%s/ in output, got:\"\n", e_expect
            printf "        echo \"stdout: $output\"\n"
            printf "        echo \"stderr: $stderr\"\n"
            printf "        false\n"
            printf "    fi\n"
        }
        printf "}\n"
    }
' "$MANIFEST"
} > "$OUT"

chmod +x "$OUT"
n=$(grep -c '^@test ' "$OUT")
echo "[generate-pipelines] wrote $OUT ($n tests)"
